// app.config.js: importeer dit bestand als allereerste, vóór de eerste component van Flux (zie het recept
// Configuratie). setPreferences werkt enkel zolang FluxConfig nog niet gelezen werd.
import { FluxConfig } from '@domg-wc/common';

FluxConfig.setPreferences({ prozaDomain: 'mockdomain' });

// main.js
import './app.config.js';
import { registerWebComponents } from '@domg-wc/common';
import { VlAlert, vlProza } from '@domg-wc/components/block';
import { html, render } from 'lit';

registerWebComponents([VlAlert]);

// vlProza is een Lit directive: ze werkt enkel in een Lit-template, bv. in de render() van een LitElement. Tijdens
// het laden toont het attribuut de fallback (standaard de code), daarna de tekst van het bericht zonder HTML-tags.
// Het bericht komt uit de cache van vl-proza-message-preloader, of van proza/domein/{domein}/{code} relatief tov de
// huidige url (of achter de optie baseUrl); in Storybook antwoordt een mock.
// Zonder domein, niet in FluxConfig en niet in de opties, gooit vlProza een fout.
render(
    html`
        <vl-alert icon="warning" title=${vlProza('alert.titel')} type="warning" closable></vl-alert>
        <vl-alert icon="info-circle" title=${vlProza('alert.bericht')} type="info"></vl-alert>
    `,
    document.body
);

