import { FluxConfig } from '@domg-wc/common';

FluxConfig.setPreferences({ prozaDomain: 'mockdomain' });

// main.js
import './app.config.js';
import { registerWebComponents } from '@domg-wc/common';
import { VlAlert, vlProza } from '@domg-wc/components/block';
import { html, render } from 'lit';

registerWebComponents([VlAlert]);

// In de mock van Storybook is het bericht welkom.titel '<p>Welkom, ${parameter.naam}!</p>'. vlProza vervangt
// ${parameter.naam} door Jan en strip de tags: de titel wordt 'Welkom, Jan!'.
render(
    html`
        <vl-alert
            icon="user"
            title=${vlProza('welkom.titel', { parameters: { naam: 'Jan' } })}
            type="success"
        ></vl-alert>
    `,
    document.body
);

// app.config.js: importeer dit bestand als allereerste, vóór de eerste component van Flux (zie het recept
// Configuratie). setPreferences werkt enkel zolang FluxConfig nog niet gelezen werd.
import { FluxConfig } from '@domg-wc/common';

FluxConfig.setPreferences({ prozaDomain: 'mockdomain' });

// main.js
import './app.config.js';
import { registerWebComponents } from '@domg-wc/common';
import { VlAlert, vlProza } from '@domg-wc/components/block';
import { html, render } from 'lit';

registerWebComponents([VlAlert]);

// De optie domain gaat voor op het domein uit FluxConfig, enkel voor deze aanroep.
render(
    html`
        <!-- Met het default domein uit FluxConfig -->
        <vl-alert icon="warning" title=${vlProza('alert.titel')} type="warning"></vl-alert>

        <!-- Met een ander domein (override) -->
        <vl-alert
            icon="info-circle"
            title=${vlProza('alert.titel', { domain: 'otherdomain' })}
            type="info"
        ></vl-alert>
    `,
    document.body
);
